/// Rows `start..start + n` of the stream. `y` is null every 7th row, `w` is
/// zero every 11th, the session turns over at row 45, and `y2` -- the `holt`
/// target -- is never null and trends.
fn frame(start: usize, n: usize) -> DataFrame {
    fn lcg(state: &mut u64) -> f64 {
        *state = state
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        (*state >> 11) as f64 / (1u64 << 53) as f64
    }
    let mut t = Vec::with_capacity(n);
    let mut sess = Vec::with_capacity(n);
    let mut x0 = Vec::with_capacity(n);
    let mut x1 = Vec::with_capacity(n);
    let mut y = Vec::with_capacity(n);
    let mut y2 = Vec::with_capacity(n);
    let mut w = Vec::with_capacity(n);
    for i in start..start + n {
        let mut s = (i as u64) ^ 0x51AF_D6ED_4A1C_93B7;
        let a = lcg(&mut s) - 0.5;
        let b = 0.4 * a + 0.6 * (lcg(&mut s) - 0.5);
        let e = 0.1 * (lcg(&mut s) - 0.5);
        t.push(i as f64);
        sess.push(if i < 45 { "s0" } else { "s1" }.to_string());
        x0.push(a);
        x1.push(b);
        y.push((i % 7 != 3).then_some(1.5 * a - 0.7 * b + 0.3 + e));
        y2.push(2.0 + 0.05 * i as f64 + 0.5 * b + e);
        w.push(if i % 11 == 4 { 0.0 } else { 1.0 });
    }
    df!(
        "t" => t, "sess" => sess, "x0" => x0, "x1" => x1,
        "y" => y, "y2" => y2, "w" => w
    )
    .unwrap()
}

/// The specs the fixture was generated from, as written. The file carries
/// its own copy, and `the_fixture_is_what_it_says` checks they agree.
fn generator_specs() -> Vec<Spec> {
    serde_json::from_str(
        r#"[
            {"name": "rw", "model": {"type": "ew_ridge", "ridge": 1e-6,
             "standardize": true, "max_rows_between_solves": 1, "window": 25.0},
             "features": ["x0", "x1"], "targets": ["y"], "clock": "t",
             "halflife": 12.0, "max_dclock": 5.0, "weight": "w"},
            {"name": "rs", "model": {"type": "ew_ridge", "ridge": 1e-6,
             "max_rows_between_solves": 1, "session_shrink": 0.5,
             "long_halflife": 80.0},
             "features": ["x0", "x1"], "targets": ["y", "y2"], "clock": "t",
             "halflife": 10.0, "max_dclock": 5.0, "weight": "w",
             "session": "sess", "session_gap": 2.0},
            {"name": "rb", "model": {"type": "ew_ridge", "ridge": 1e-6,
             "standardize": true, "gram_block_rows": 8, "solve_every": 5.0,
             "max_rows_between_solves": 10},
             "features": ["x0", "x1"], "targets": ["y"], "clock": "t",
             "halflife": 15.0, "max_dclock": 5.0, "weight": "w"},
            {"name": "ho", "model": {"type": "holt", "trend_halflife": 24.0},
             "features": [], "targets": ["y2"], "clock": "t",
             "halflife": 6.0, "max_dclock": 5.0, "min_periods": 0.0}
        ]"#,
    )
    .unwrap()
}

const NAMES: [&str; 4] = ["rw", "rs", "rb", "ho"];

fn bytes() -> Vec<u8> {
    (0..SCHEMA6_RIDGE_HEX.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&SCHEMA6_RIDGE_HEX[i..i + 2], 16).unwrap())
        .collect()
}

fn specs_from_fixture() -> Vec<Spec> {
    Bank::load_bytes(&bytes(), None)
        .expect("the fixture should load without spec expectations")
        .specs()
        .to_vec()
}

fn header(bytes: &[u8]) -> serde_json::Value {
    rmp_serde::from_slice(bytes).expect("a bank file is a msgpack map")
}

/// The bank the fixture is a snapshot of, built afresh in this build.
fn fresh() -> Bank {
    let mut bank = Bank::new(specs_from_fixture()).unwrap();
    for start in (0..90).step_by(30) {
        bank.fit_predict(&frame(start, 30)).unwrap();
    }
    bank
}

/// One frame per spec, unnested, so the comparison sees every field.
fn unnested(n: usize, cols: Vec<Column>) -> Vec<DataFrame> {
    let df = DataFrame::new(n, cols).unwrap();
    NAMES
        .iter()
        .map(|name| df.select([*name]).unwrap().unnest([*name], None).unwrap())
        .collect()
}

/// A column's values as floats, a list column's flattened in order.
fn floats(c: &Column) -> Vec<Option<f64>> {
    let s = c.as_materialized_series();
    if let DataType::List(_) = s.dtype() {
        s.list()
            .unwrap()
            .amortized_iter()
            .flat_map(|v| match v {
                Some(v) => v
                    .as_ref()
                    .cast(&DataType::Float64)
                    .unwrap()
                    .f64()
                    .unwrap()
                    .iter()
                    .collect::<Vec<_>>(),
                None => vec![None],
            })
            .collect()
    } else {
        s.cast(&DataType::Float64)
            .unwrap()
            .f64()
            .unwrap()
            .iter()
            .collect()
    }
}

/// Every value within `rtol` of the other's, relative to `1 + |value|`,
/// with nulls and NaNs in the same places: what a conversion from raw to
/// centred moments can promise. `rtol = 0` is equality.
fn assert_values(want: &[Option<f64>], got: &[Option<f64>], rtol: f64, what: &str) {
    assert_eq!(want.len(), got.len(), "{what}: length");
    for (i, (a, b)) in want.iter().zip(got).enumerate() {
        match (a, b) {
            (None, None) => {}
            (Some(a), Some(b)) if a.is_nan() && b.is_nan() => {}
            (Some(a), Some(b)) => assert!(
                (a - b).abs() <= rtol * (1.0 + a.abs()),
                "{what}: value {i}: {a} vs {b}"
            ),
            _ => panic!("{what}: value {i}: {a:?} vs {b:?}"),
        }
    }
}

fn assert_close(want: &DataFrame, got: &DataFrame, rtol: f64, what: &str) {
    assert_eq!(
        want.get_column_names(),
        got.get_column_names(),
        "{what}: columns"
    );
    for (w, g) in want.columns().iter().zip(got.columns()) {
        assert_values(
            &floats(w),
            &floats(g),
            rtol,
            &format!("{what}: {}", w.name()),
        );
    }
}

/// The tolerance a spec is held to: `1e-12` where the load converted raw
/// moments to centred ones, the bit where it did not.
fn rtol(name: &str) -> f64 {
    if name.starts_with('r') { 1e-12 } else { 0.0 }
}

/// Each spec's coefficients, with the weight behind each fit ahead of it.
fn coefs(bank: &Bank) -> Vec<Vec<Option<f64>>> {
    (0..NAMES.len())
        .map(|si| {
            let mut out = Vec::new();
            for c in bank.coef(si, None).unwrap() {
                out.push(Some(c.n_eff));
                match c.coef {
                    Some(v) => out.extend(v.into_iter().map(Some)),
                    None => out.push(None),
                }
            }
            out
        })
        .collect()
}

fn assert_same_fit(want: &Bank, got: &Bank, what: &str) {
    for (i, (w, g)) in coefs(want).iter().zip(&coefs(got)).enumerate() {
        assert_values(w, g, rtol(NAMES[i]), &format!("{what}: {} coef", NAMES[i]));
    }
}

#[test]
fn the_fixture_is_what_it_says() {
    let h = header(&bytes());
    assert_eq!(h["format_version"], 2);
    assert_eq!(h["schema_version"], 6);
    let specs = specs_from_fixture();
    let names: Vec<&str> = specs.iter().map(|s| s.name.as_str()).collect();
    assert_eq!(names, NAMES);
    let mut want = generator_specs();
    want.iter_mut().for_each(Spec::fill_defaults);
    assert_eq!(
        serde_json::to_value(&specs).unwrap(),
        serde_json::to_value(&want).unwrap()
    );
}

#[test]
fn a_schema_6_ridge_state_loads_and_continues_the_stream() {
    let specs = specs_from_fixture();
    let mut want = fresh();
    let mut restored = Bank::load_bytes(&bytes(), Some(&specs)).unwrap();
    assert_same_fit(&want, &restored, "as loaded");
    let next = frame(90, 30);
    let a = unnested(next.height(), want.fit_predict(&next).unwrap());
    let b = unnested(next.height(), restored.fit_predict(&next).unwrap());
    for (i, (w, g)) in a.iter().zip(&b).enumerate() {
        assert_close(w, g, rtol(NAMES[i]), &format!("continuing: {}", NAMES[i]));
    }
    assert_same_fit(&want, &restored, "after continuing");
}

#[test]
fn a_schema_6_ridge_state_re_saves_in_the_current_layout() {
    let restored = Bank::load_bytes(&bytes(), None).unwrap();
    let again = restored.save_bytes().unwrap();
    let h = header(&again);
    assert_eq!(h["schema_version"], online_core::SCHEMA_VERSION);
    if online_core::SCHEMA_VERSION != 6 {
        assert_ne!(again, bytes(), "saving should write the current layout");
    }
    // What was converted once is the state from then on: the re-saved file
    // loads to the same bits and continues identically.
    let mut reloaded = Bank::load_bytes(&again, None).unwrap();
    let mut restored = restored;
    assert_eq!(reloaded.save_bytes().unwrap(), again, "a second save moved");
    let next = frame(90, 30);
    let a = unnested(next.height(), restored.fit_predict(&next).unwrap());
    let b = unnested(next.height(), reloaded.fit_predict(&next).unwrap());
    for (i, (w, g)) in a.iter().zip(&b).enumerate() {
        assert_close(w, g, 0.0, &format!("after re-save: {}", NAMES[i]));
    }
}

/// Generated the fixture: `cargo test -p online-polars --test
/// state_schema6_ridge print_fixture -- --ignored --nocapture`, on the last
/// schema-6 build. Kept for the record; do not regenerate it from a later
/// layout -- the point of the file is that a schema-6 writer's bytes load.
#[test]
#[ignore]
fn print_fixture() {
    let mut bank = Bank::new(generator_specs()).unwrap();
    for start in (0..90).step_by(30) {
        bank.fit_predict(&frame(start, 30)).unwrap();
    }
    let bytes = bank.save_bytes().unwrap();
    let hex: String = bytes.iter().map(|b| format!("{b:02x}")).collect();
    println!("HEX_BEGIN");
    for line in hex.as_bytes().chunks(76) {
        println!("    \"{}\",", std::str::from_utf8(line).unwrap());
    }
    println!("HEX_END");
}
